import os
import hashlib
import logging
from flask import Flask, request, jsonify, send_file
from functools import wraps

app = Flask(__name__)
logger = logging.getLogger(__name__)

# CI/CD Pipeline Artifact Plugin
# Serves build artifacts from pipeline workspace directories

PIPELINE_WORKSPACE = '/var/lib/jenkins/workspace'
ALLOWED_EXTENSIONS = {'.log', '.xml', '.json', '.txt', '.html', '.tar.gz'}

def validate_api_key(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        api_key = request.headers.get('X-Pipeline-Key')
        if not api_key:
            return jsonify({'error': 'Missing API key'}), 401
        expected = os.environ.get('PIPELINE_API_KEY', '')
        if not hashlib.sha256(api_key.encode()).hexdigest() == hashlib.sha256(expected.encode()).hexdigest():
            return jsonify({'error': 'Invalid API key'}), 403
        return f(*args, **kwargs)
    return decorated

def check_extension(filename):
    """Verify file has an allowed extension"""
    for ext in ALLOWED_EXTENSIONS:
        if filename.endswith(ext):
            return True
    return False

@app.route('/api/v1/artifacts/<pipeline_id>', methods=['GET'])
@validate_api_key
def get_artifact(pipeline_id):
    """Retrieve a build artifact from a pipeline run.

    Query params:
        path: relative path to artifact within pipeline workspace
        format: optional, 'raw' or 'base64'
    """
    artifact_path = request.args.get('path', '')

    if not artifact_path:
        return jsonify({'error': 'path parameter required'}), 400

    # Sanitize pipeline_id - alphanumeric and hyphens only
    if not all(c.isalnum() or c in '-_' for c in pipeline_id):
        return jsonify({'error': 'Invalid pipeline ID'}), 400

    # Build full path
    full_path = os.path.join(PIPELINE_WORKSPACE, pipeline_id, artifact_path)

    # Extension check
    if not check_extension(artifact_path):
        return jsonify({'error': 'File type not allowed'}), 403

    # Check file exists
    if not os.path.isfile(full_path):
        return jsonify({'error': 'Artifact not found'}), 404

    logger.info(f'Serving artifact: {full_path} for pipeline {pipeline_id}')

    output_format = request.args.get('format', 'raw')
    if output_format == 'raw':
        return send_file(full_path)
    elif output_format == 'base64':
        import base64
        with open(full_path, 'rb') as f:
            content = base64.b64encode(f.read()).decode()
        return jsonify({'content': content, 'encoding': 'base64'})
    else:
        return jsonify({'error': 'Invalid format'}), 400


@app.route('/api/v1/artifacts/<pipeline_id>/list', methods=['GET'])
@validate_api_key
def list_artifacts(pipeline_id):
    """List available artifacts for a pipeline run."""
    if not all(c.isalnum() or c in '-_' for c in pipeline_id):
        return jsonify({'error': 'Invalid pipeline ID'}), 400

    subdir = request.args.get('subdir', '')
    target_dir = os.path.join(PIPELINE_WORKSPACE, pipeline_id, subdir)

    if not os.path.isdir(target_dir):
        return jsonify({'error': 'Directory not found'}), 404

    files = []
    for entry in os.listdir(target_dir):
        entry_path = os.path.join(target_dir, entry)
        if os.path.isfile(entry_path) and check_extension(entry):
            files.append({'name': entry, 'size': os.path.getsize(entry_path)})

    return jsonify({'pipeline_id': pipeline_id, 'artifacts': files})


@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})


if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8443)
